import React from 'react';
import { graphql } from 'gatsby';
import Layout from '../components/Layout';
import Intro from '../components/Intro';
import PostList from '../components/PostList';

export default function CategoryTemplate({ data, pageContext }) {
  const posts = data.allMdx.nodes.map(n => ({
    slug:     `/posts${n.fields.slug}/`,
    title:    n.frontmatter.title,
    date:     n.frontmatter.date,
    category: n.frontmatter.category,
    dek:      n.frontmatter.dek,
    readTime: n.fields.readTime,
  }));
  return (
    <Layout active="articles">
      <Intro
        eyebrow="Category"
        title={pageContext.category}
        essayCount={posts.length}
        updatedAt={posts[0]?.date}
      />
      <div style={{ maxWidth: 820, margin: '0 auto', paddingBottom: 80 }}>
        <PostList posts={posts} />
      </div>
    </Layout>
  );
}

export const query = graphql`
  query CategoryQuery($category: String!) {
    allMdx(
      filter: { frontmatter: { category: { eq: $category }, draft: { ne: true } } }
      sort: { frontmatter: { date: DESC } }
    ) {
      nodes {
        fields { slug readTime }
        frontmatter {
          title
          date(formatString: "MMMM YYYY")
          category
          dek
        }
      }
    }
  }
`;
