import React from 'react';
import { Link } from 'gatsby';

const CATEGORY_HUES = {
  'AI':                      260,
  'Algorithm':               150,
  'Amazon':                   30,
  'CI/CD':                   270,
  'Functional Programming':  175,
  'GatsbyJS':                200,
  'General':                  35,
  'GraphQL':                 315,
  'Kubernetes':              210,
  'MeteorJS':                190,
  'Professional Growth':      45,
  'Rails':                   350,
  'Reactive Programming':    185,
  'Repository Manager':      240,
  'REST APIs':                90,
  'Ruby':                    355,
  'State Management':        195,
};

function PostArt({ category }) {
  const hue  = CATEGORY_HUES[category] ?? 220;
  const hue2 = (hue + 35) % 360;
  const id   = `g-${category.replace(/[^a-z0-9]/gi, '-').toLowerCase()}`;
  return (
    <div className="post-art" aria-hidden="true">
      <svg
        width="100%" height="100%"
        xmlns="http://www.w3.org/2000/svg"
        preserveAspectRatio="xMidYMid slice"
        style={{ display: 'block', width: '100%', height: '100%' }}
      >
        <defs>
          <linearGradient id={id} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%"   stopColor={`hsl(${hue},  60%, 58%)`} />
            <stop offset="100%" stopColor={`hsl(${hue2}, 50%, 40%)`} />
          </linearGradient>
        </defs>
        <rect width="100%" height="100%" fill={`url(#${id})`} />
        {/* subtle overlapping circles for depth */}
        <circle cx="85%" cy="15%" r="70"  fill="rgba(255,255,255,0.09)" />
        <circle cx="15%" cy="85%" r="90"  fill="rgba(255,255,255,0.07)" />
        <circle cx="55%" cy="55%" r="45"  fill="rgba(255,255,255,0.06)" />
        <circle cx="80%" cy="75%" r="30"  fill="rgba(0,0,0,0.08)" />
        {/* category label */}
        <text
          x="50%" y="92%"
          textAnchor="middle"
          fontFamily="'IBM Plex Mono', monospace"
          fontSize="9"
          letterSpacing="0.12em"
          textTransform="uppercase"
          fill="rgba(255,255,255,0.45)"
        >
          {category.toUpperCase()}
        </text>
      </svg>
    </div>
  );
}

export function FeaturedPost({ post, num }) {
  return (
    <article className="post featured">
      <div className="post-num">{num}</div>
      <div>
        <div className="post-meta">
          <span className="post-date">{post.date}</span>
          <Link to={`/category/${post.category.toLowerCase().replace(/[^a-z0-9]+/g, '-')}/`} className="post-cat">
            {post.category}
          </Link>
          <span>{post.readTime} read</span>
        </div>
        <h2 className="post-title"><Link to={post.slug}>{post.title}</Link></h2>
        <p className="post-dek">{post.dek}</p>
        <Link className="post-link" to={post.slug}>Read essay →</Link>
      </div>
      {post.coverUrl
        ? <div className="post-art"><img src={post.coverUrl} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} /></div>
        : <PostArt category={post.category} />
      }
    </article>
  );
}

export function PostCard({ post, num }) {
  return (
    <article className="post row">
      <div className="post-num">{num}</div>
      <div>
        <div className="post-meta">
          <span className="post-date">{post.date}</span>
          <Link to={`/category/${post.category.toLowerCase().replace(/[^a-z0-9]+/g, '-')}/`} className="post-cat">
            {post.category}
          </Link>
          <span>{post.readTime} read</span>
        </div>
        <h3 className="post-title"><Link to={post.slug}>{post.title}</Link></h3>
        <p className="post-dek">{post.dek}</p>
        <Link className="post-link" to={post.slug}>Read →</Link>
      </div>
    </article>
  );
}

export default function PostList({ posts }) {
  if (!posts || posts.length === 0) {
    return <div className="empty">No essays match.</div>;
  }
  const [featured, ...rest] = posts;
  return (
    <section className="posts">
      <FeaturedPost post={featured} num="01" />
      {rest.map((p, i) => (
        <PostCard key={p.slug} post={p} num={String(i + 2).padStart(2, '0')} />
      ))}
    </section>
  );
}
